function CourseDetails({ course }) {
  if (!course.duration) return null;
  return (
    <div className="glam-course-details">
      <p className="glam-course-duration">{course.duration}</p>
      <p className="glam-course-includes">{course.includes}</p>
      <dl className="glam-course-fees">
        <div><dt>Cost</dt><dd>{course.cost}</dd></div>
        <div><dt>Admin fee</dt><dd>{course.adminFee}</dd></div>
      </dl>
    </div>
  );
}

function CourseDialog({ course, onClose }) {
  const dialogRef = useRef(null);

  useEffect(() => {
    const dialog = dialogRef.current;
    if (course && !dialog.open) dialog.showModal();
    else if (!course && dialog.open) dialog.close();
  }, [course]);

  function handleBackdropClick(event) {
    if (event.target !== event.currentTarget) return;

    const bounds = event.currentTarget.getBoundingClientRect();

    if (
      event.clientX < bounds.left ||
      event.clientX > bounds.right ||
      event.clientY < bounds.top ||
      event.clientY > bounds.bottom
    ) {
      event.currentTarget.close();
    }
  }

  return (
    <dialog
      ref={dialogRef}
      className="course-dialog"
      aria-labelledby="course-dialog-title"
      onClose={onClose}
      onClick={handleBackdropClick}
    >
      <button
        className="dialog-close"
        aria-label="Close course details"
        onClick={() => dialogRef.current.close()}
      >
        ×
      </button>

      {course && (
        <>
          <p className="eyebrow">GLAM CO ACADEMY / TRAINING</p>
          <h2 id="course-dialog-title">{course.title}</h2>
          <img
            className="glam-training-photo"
            src={course.image || trainingImage}
            alt={course.imageAlt || "Glam Co practitioner demonstrating a beauty treatment"}
          />
          <p>{course.description}</p>
          <CourseDetails course={course} />

          <div className="dialog-details">
            <p>
              <strong>Our approach</strong><br />
              Professional theory and hands-on practical training in a
              supportive learning environment.
            </p>
            <p>
              <strong>Before you enrol</strong><br />
              Confirm course content, entry requirements, fees, dates, and
              professional scope with the academy.
            </p>
          </div>

          <button
            className="button button-dark"
            onClick={() => dialogRef.current.close()}
          >
            Continue exploring
          </button>
        </>
      )}
    </dialog>
  );
}

